import { useMemo, useState } from "react";
import { createRoot } from "react-dom/client";

import ThreadPanel from "./components/ThreadPanel";
import fixtures from "./fixtures.json";
import type { Action, Patient } from "./types";
import "./theme.css";

/** Development harness. Not part of the remote.
 *
 *  fixtures.json is GENERATED by scripts/gen-fixtures.py from the real
 *  derivation in care_phc/thread.py, so what you see here is what the backend
 *  would return, not a second implementation of the rules in TypeScript.
 *  Regenerate with `npm run fixtures`. */

type Fx = {
  bundles: Record<string, string[]>;
  patients: (Patient & {
    flags: string[];
    station: string | null;
    actions: Record<string, Action[]>;
  })[];
};

const fx = fixtures as Fx;

const LABELS: Record<string, string> = {
  frontdesk: "Front desk", nurse: "Nurse", mo: "Medical officer",
  lab: "Lab technician", lab_incharge: "Lab in-charge", pharmacist: "Pharmacist",
  asha: "ASHA", anm: "ANM", cho: "CHO",
};

function App() {
  const [pi, setPi] = useState(0);
  const [bundle, setBundle] = useState("mo");
  const [dark, setDark] = useState(false);
  const [picked, setPicked] = useState<string | null>(null);

  document.documentElement.dataset.theme = dark ? "dark" : "light";
  document.body.style.background = "var(--canvas)";

  const p = fx.patients[pi];
  const thread = useMemo(
    () => ({
      patient: { name: p.name, age: p.age, sex: p.sex, village: p.village, note: p.note },
      flags: p.flags,
      station: p.station,
      actions: p.actions[bundle] ?? [],
    }),
    [p, bundle],
  );

  return (
    <div className="phc" style={{ maxWidth: 760, margin: "0 auto", padding: 24 }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 4 }}>
        <h1 style={{ font: "600 17px Inter, system-ui", margin: 0, letterSpacing: "-.01em" }}>
          PHC Yadiki
        </h1>
        <span style={{ color: "var(--ink-3)", fontSize: 12.5 }}>Anantapur · patient thread</span>
        <button
          onClick={() => setDark(!dark)}
          style={{
            marginLeft: "auto", font: "inherit", fontSize: 12, cursor: "pointer",
            padding: "5px 11px", borderRadius: 999, border: "1px solid var(--border)",
            background: "var(--surface)", color: "var(--ink-2)",
          }}
        >
          {dark ? "Light" : "Dark"}
        </button>
      </div>
      <p style={{ color: "var(--ink-3)", fontSize: 12.5, margin: "0 0 18px" }}>
        Actions below are generated from the operation catalogue and ordered by the
        guard. Switch the cadre to see the same patient's thread from another station.
      </p>

      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 10 }}>
        {fx.patients.map((q, i) => (
          <button
            key={q.name}
            onClick={() => setPi(i)}
            className="phc-chip"
            style={{
              cursor: "pointer",
              borderColor: i === pi ? "var(--ink)" : undefined,
              color: i === pi ? "var(--ink)" : undefined,
            }}
          >
            {q.name}
          </button>
        ))}
      </div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 16 }}>
        {Object.keys(fx.bundles).map((b) => (
          <button
            key={b}
            onClick={() => setBundle(b)}
            className="phc-chip"
            style={{
              cursor: "pointer",
              background: b === bundle ? "var(--ink)" : undefined,
              borderColor: b === bundle ? "var(--ink)" : undefined,
              color: b === bundle ? "var(--surface)" : undefined,
            }}
          >
            {LABELS[b] ?? b}
          </button>
        ))}
      </div>

      <ThreadPanel
        thread={thread}
        bundleLabel={LABELS[bundle] ?? bundle}
        onAction={(a) => setPicked(a.tool)}
      />
      {picked && (
        <p style={{ color: "var(--ink-3)", fontSize: 12.5, marginTop: 14 }}>
          Would call <code>{picked}</code> on the guard. No backend in the harness.
        </p>
      )}
    </div>
  );
}

createRoot(document.getElementById("root")!).render(<App />);
